import{_ as t,o as a,c as s,a6 as o}from"./chunks/framework.CcG9dYYo.js";const p=JSON.parse('{"title":"Getting AI Help","description":"Get Claude to design and write LCARdS dashboards with you using the LCARdS skill: setup for Claude Code and claude.ai, what to ask, previews and checks, connecting Home Assistant with ha-mcp, and what to give other assistants.","frontmatter":{"description":"Get Claude to design and write LCARdS dashboards with you using the LCARdS skill: setup for Claude Code and claude.ai, what to ask, previews and checks, connecting Home Assistant with ha-mcp, and what to give other assistants.","moved_anchors":{"if-it-still-makes-things-up":"/getting-started/ai-assistance#check-what-it-wrote"}},"headers":[],"relativePath":"getting-started/ai-assistance.md","filePath":"getting-started/ai-assistance.md","lastUpdated":1795368173000}'),n={name:"getting-started/ai-assistance.md"};function r(i,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="getting-ai-help" tabindex="-1">Getting AI Help <a class="header-anchor" href="#getting-ai-help" aria-label="Permalink to &quot;Getting AI Help&quot;">​</a></h1><p><strong>Claude with the LCARdS skill can plan a dashboard with you, write the YAML and check it before you paste anything.</strong></p><ul><li>Out of the box, a chatbot has never seen LCARdS. It guesses option names, and LCARdS silently ignores the guesses.</li><li>The skill gives Claude the real options, presets, colours, docs, gallery dashboards and config checker for your LCARdS version, and the astrometrics starters with their settings, so it can link a starter to your entities (a wormhole that opens with a light).</li><li>The skill is made for Claude. Other assistants can still help if you give them the option list (see <a href="#with-other-assistants">With other assistants</a>).</li></ul><h2 id="with-claude-easiest" tabindex="-1">With Claude (easiest) <a class="header-anchor" href="#with-claude-easiest" aria-label="Permalink to &quot;With Claude (easiest)&quot;">​</a></h2><p><strong>Install the LCARdS skill once, then ask in plain words.</strong></p><ul><li>The skill also knows <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS</a> (its themes and <code>--lcars-*</code> colours) and the <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">UIX</a> styling it runs on, so Claude can tell you whether a job belongs to an LCARdS option, the theme or UIX.</li><li>Claude uses your real entity ids: tell it them, or connect it to Home Assistant with <a href="#give-claude-your-home-s-context-ha-mcp">ha-mcp</a>.</li></ul><table tabindex="0"><thead><tr><th>Where you use Claude</th><th>How to add the skill</th></tr></thead><tbody><tr><td><strong>Claude Code</strong></td><td>Run <code>/plugin marketplace add https://lcards.unimatrix01.ca/marketplace.json</code>, then <code>/plugin install lcards@lcards</code></td></tr><tr><td><strong>claude.ai or the Claude apps</strong></td><td>Open <strong>Plugins</strong>, choose <strong>Add</strong>, then <strong>Marketplace</strong> and <strong>Repository</strong>, and enter <code>snootched/lcards</code>. Install <strong>lcards</strong> from it. Turn on code execution</td></tr></tbody></table><details class="details custom-block"><summary>More about setup</summary><ul><li><strong>What the plugin runs:</strong> besides text, it holds a few small offline programs, all of them listed in its <a href="https://github.com/snootched/lcards/blob/main/plugins/lcards/README.md" target="_blank" rel="noreferrer">README</a>. Claude runs the config checker on its drafts (in claude.ai inside its code execution sandbox, not on your computer). In Claude Code a hook also runs the checker after Claude writes a YAML file with LCARdS config, and the starter tool and preview link maker run when Claude needs them. None of them connect to the internet, install anything or read files beyond the one they are given; the preview link keeps your YAML after the <code>#</code>, which browsers never send to a server.</li><li><strong>Pictures in claude.ai:</strong> to see pictures of gallery screens while you plan, allow network access to <code>lcards.unimatrix01.ca</code> in the code execution settings (add it to the allowed domains, or allow all domains). Without it, Claude gives you the links instead.</li><li><strong>Updating on claude.ai:</strong> the marketplace follows LCARdS releases. Open it under <strong>Plugins</strong> and check for updates after a release.</li><li><strong>claude.ai without the marketplace:</strong> download <a href="/tools/lcards-plugin.zip"><code>lcards-plugin.zip</code></a> and upload it under <strong>Plugins</strong> (<strong>Add</strong>, then <strong>Upload plugin</strong>). You upload the new zip yourself after each release. The skill alone, <a href="/tools/lcards-skill.zip"><code>lcards-skill.zip</code></a>, also uploads as a custom skill, without the slash commands.</li><li><strong>Claude Code from the repository:</strong> <code>/plugin marketplace add snootched/lcards</code> adds the same marketplace claude.ai uses. The command in the table above follows the docs site instead, which also has the dev channel. Add one of them, not both: both are named <strong>lcards</strong>.</li><li><strong>Updating the Claude Code plugin:</strong> each LCARdS release comes with a new version. Run <code>/plugin marketplace update lcards</code>, or open <code>/plugin</code>, go to <strong>Marketplaces</strong>, select <strong>lcards</strong> and turn on <strong>Enable auto-update</strong>. Then run <code>/reload-plugins</code> or start a new session. The plugin needs Claude Code 2.1.224 or newer.</li><li><strong>Installed the skill by hand before?</strong> Delete <code>~/.claude/skills/lcards/</code> first, so only the plugin copy loads.</li><li><strong>Manual install in Claude Code:</strong> unzip <a href="/tools/lcards-skill.zip"><code>lcards-skill.zip</code></a> into <code>~/.claude/skills/</code>, so you have <code>~/.claude/skills/lcards/SKILL.md</code>. It won&#39;t update itself.</li><li><strong>Running a dev build of LCARdS?</strong> Use the dev channel, which follows the <a href="https://lcards.unimatrix01.ca/dev/" target="_blank" rel="noreferrer">dev docs</a>: <code>/plugin marketplace add https://lcards.unimatrix01.ca/dev/marketplace.json</code>, then <code>/plugin install lcards@lcards-dev</code>. Install one channel, not both.</li><li><strong>Other tools:</strong> the skill follows the open <a href="https://agentskills.io" target="_blank" rel="noreferrer">Agent Skills</a> standard, so other tools may load the zip. We build and test it with Claude only.</li></ul></details><h2 id="what-to-ask" tabindex="-1">What to ask <a class="header-anchor" href="#what-to-ask" aria-label="Permalink to &quot;What to ask&quot;">​</a></h2><p><strong>Ask for what you want; Claude works out the rest with you.</strong></p><table tabindex="0"><thead><tr><th>You ask</th><th>Claude</th></tr></thead><tbody><tr><td><em>&quot;I want a Star Trek engineering screen for my house. What could I do?&quot;</em></td><td>Asks what the screen is for, where it runs, the look, how colours should work and which entities to use. Then offers two or three concepts, each with a layout sketch and pictures of similar gallery screens</td></tr><tr><td><em>&quot;Build an engineering dashboard with my <code>sensor.power_*</code> entities.&quot;</em></td><td>Proposes a design for those entities, builds it once you agree, and checks it</td></tr><tr><td><em>&quot;Make me an LCARdS button for <code>light.kitchen</code> that turns red when it&#39;s on.&quot;</em></td><td>Writes the card straight away</td></tr><tr><td><em>&quot;Just the YAML.&quot;</em></td><td>Skips the questions and picks sensible defaults</td></tr><tr><td><em>&quot;Can I see it first?&quot;</em></td><td>Gives you a file that opens the draft on <a href="./preview.html">Preview Your YAML</a>, as real cards</td></tr><tr><td><em>&quot;Check this LCARdS config and fix it.&quot;</em></td><td>Runs the same checker as <a href="./config-checker.html">Check Your Config</a> and explains each problem</td></tr><tr><td><em>&quot;Restyle this to the LCARS design rules.&quot;</em></td><td>Keeps your entities, controls and labels, rebuilds the dashboard with <a href="./lcars-design.html">Designing LCARS Screens</a>, then lists what changed</td></tr></tbody></table><details class="details custom-block"><summary>More about designing with Claude</summary><ul><li><strong>Features you didn&#39;t know about:</strong> each concept names the features that suit your devices, such as a yellow alert and a chirp when the door opens, a starfield that speeds up with the fan, or a schematic of your house with a light switch in every room.</li><li><strong>After the build:</strong> Claude checks its YAML with the config checker before handing it over, and adds a few ideas for later.</li><li><strong>Restyling:</strong> Claude asks about anything the YAML doesn&#39;t settle (the look, how colours work, the schematic&#39;s leader style), then grades the result against the guide&#39;s <a href="./lcars-design.html#check-a-screen">Check a screen</a> list.</li><li><strong>Screenshots:</strong> when Claude can reach your Home Assistant and a browser (for example Claude Code with ha-mcp and a browser tool), it can offer to put the draft on a separate dashboard and show you a screenshot.</li></ul></details><h2 id="in-claude-code" tabindex="-1">In Claude Code <a class="header-anchor" href="#in-claude-code" aria-label="Permalink to &quot;In Claude Code&quot;">​</a></h2><p><strong>The plugin adds an automatic check and three commands.</strong></p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th></tr></thead><tbody><tr><td>Automatic check</td><td>Runs the config checker whenever Claude writes a YAML file with LCARdS cards in it; Claude fixes what it reports before handing the file over</td></tr><tr><td><code>/lcards:check</code></td><td>Checks a file or pasted YAML and explains each problem</td></tr><tr><td><code>/lcards:dashboard</code></td><td>Designs a whole dashboard with you: a few questions to pick from, then two or three concepts side by side with a layout sketch each, then the YAML</td></tr><tr><td><code>/lcards:issue</code></td><td>Helps you write a bug report or feature request: checks your config first, cuts your YAML down to a small example, then gives you a draft to paste into the GitHub form (you submit it)</td></tr></tbody></table><h2 id="give-claude-your-home-s-context-ha-mcp" tabindex="-1">Give Claude your home&#39;s context (ha-mcp) <a class="header-anchor" href="#give-claude-your-home-s-context-ha-mcp" aria-label="Permalink to &quot;Give Claude your home&#39;s context (ha-mcp)&quot;">​</a></h2><p><strong>The community <a href="https://github.com/homeassistant-ai/ha-mcp" target="_blank" rel="noreferrer">ha-mcp</a> server connects Claude to your Home Assistant, so it can look up your setup instead of asking.</strong></p><ul><li>Claude sees your areas and floors (to group a dashboard by room), your entities and their states (so it uses your real ids), and what each device is (to pick the right card).</li><li>Then ask, for example, <em>&quot;Build an LCARdS engineering dashboard for the devices in my garage.&quot;</em></li></ul><div class="warning custom-block"><p class="custom-block-title">ha-mcp is not part of LCARdS</p><p>It is a separate community project that can also change your Home Assistant. To let Claude only read your setup, turn on its <strong>Read Only Mode</strong>, or append <code>/readonly</code> to the server address. Set it up with <a href="https://github.com/homeassistant-ai/ha-mcp" target="_blank" rel="noreferrer">its own instructions</a>.</p></div><h2 id="with-other-assistants" tabindex="-1">With other assistants <a class="header-anchor" href="#with-other-assistants" aria-label="Permalink to &quot;With other assistants&quot;">​</a></h2><p><strong>Other assistants don&#39;t get the skill&#39;s conversation, previews or checker: attach the option list for your card, and expect more rounds than with Claude.</strong></p><ol><li><p><strong>Download the option list for your card</strong>, for example <a href="/schema/cards/lcards-button.json"><code>lcards-button.json</code></a>. Every card is listed in <a href="/schema/index.json"><code>schema/index.json</code></a>.</p></li><li><p><strong>Attach it</strong> to your chat and paste this first:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m writing YAML for LCARdS, a custom Home Assistant card system. The</span></span>
<span class="line"><span>attached JSON Schema lists every option. Only use options from the schema.</span></span>
<span class="line"><span>If something I ask for isn&#39;t there, tell me instead of inventing a key.</span></span></code></pre></div></li><li><p><strong>Describe the card you want</strong>, then <a href="#check-what-it-wrote">check what it wrote</a>.</p></li></ol><h2 id="check-what-it-wrote" tabindex="-1">Check what it wrote <a class="header-anchor" href="#check-what-it-wrote" aria-label="Permalink to &quot;Check what it wrote&quot;">​</a></h2><p><strong>Check any YAML an assistant wrote before it goes on a dashboard.</strong></p><ul><li>Paste it into <a href="./config-checker.html">Check Your Config</a>. It runs in your browser and points at each problem. <a href="./preview.html">Preview Your YAML</a> shows it as real cards.</li><li>Prefer the command line? Download <a href="/tools/lcards-validate.mjs"><code>lcards-validate.mjs</code></a> and run <code>node lcards-validate.mjs my-dashboard.yaml</code> (Node.js 20 or newer).</li><li>If the assistant still makes things up, paste the checker&#39;s results back into the chat, ask it to fix exactly those lines, and remind it to re-read the attached schema instead of guessing.</li></ul><h2 id="additional-context" tabindex="-1">Additional Context <a class="header-anchor" href="#additional-context" aria-label="Permalink to &quot;Additional Context&quot;">​</a></h2><p><strong>More you can attach for a tool without the skill: the schemas, docs pages and a longer prompt.</strong> Claude with the skill already has all of it.</p><details class="details custom-block"><summary>What else you can attach</summary><p><strong>Schemas</strong></p><ul><li><strong>One card at a time (smallest):</strong> the card&#39;s file from <a href="/schema/index.json"><code>schema/index.json</code></a>, plus the shared files its entry lists under <code>uses</code> (rules, animations, background animations, state colours, filters). Card files are under 100 KB; attach only the shared files your request touches.</li><li><strong>Everything in one file:</strong> <a href="/lcards-schema.json"><code>lcards-schema.json</code></a> holds every card, the <a href="./../cards/layout-view/">Layout View</a> and the LCARS shell strategy. It is about 800 KB, so it suits tools with large context windows.</li><li>Each GitHub release carries both (<code>lcards-schema.json</code>, <code>lcards-schema.zip</code>), plus the skill and the checker, matching that release exactly.</li></ul><p><strong>Docs pages</strong></p><ul><li><a href="./../cards/common.html">Common Properties</a> explains what the schema can&#39;t: entity references, the <code>theme:</code> prefix, <code>{{ }}</code> templates and actions.</li><li>The card&#39;s own page (for example <a href="./../cards/button/">Button</a> or <a href="./../cards/chart/">Chart</a>) has worked examples.</li><li>Tools that read <a href="/llms.txt"><code>llms.txt</code></a> find everything from there. <a href="/llms-full.txt"><code>llms-full.txt</code></a> is all the user docs in one file.</li></ul><p><strong>MSD</strong></p><p>The MSD schema (<code>custom:lcards-msd-card</code>) is large and deeply nested. Attach <a href="/schema/cards/lcards-msd-card.json"><code>lcards-msd-card.json</code></a> with the shared files it uses, plus the <a href="./../cards/msd/quick-start.html">MSD Getting Started</a> or <a href="./../cards/msd/routing.html">Line Routing</a> page, and expect a few more rounds than for a single button.</p><p><strong>Longer prompt template</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m writing YAML configuration for LCARdS, a custom Home Assistant Lovelace</span></span>
<span class="line"><span>card system. I&#39;ve attached its JSON Schema (from https://lcards.unimatrix01.ca/schema/index.json)</span></span>
<span class="line"><span>and reference docs. Rules:</span></span>
<span class="line"><span>- Only use properties that appear in the schema for the card type I&#39;m using</span></span>
<span class="line"><span>  (resolve &quot;#/$defs/...&quot; refs within the file, and &quot;../shared/&lt;name&gt;.json&quot; refs</span></span>
<span class="line"><span>  against the shared files I attached).</span></span>
<span class="line"><span>- Do not invent properties. If something I ask for isn&#39;t in the schema, tell</span></span>
<span class="line"><span>  me instead of guessing at a plausible-sounding key.</span></span>
<span class="line"><span>- Colour values must match the schema&#39;s colour pattern: hex, rgb()/rgba()/</span></span>
<span class="line"><span>  hsl()/hsla(), var(--name), or a theme:path token (e.g. theme:colors.ui.primary).</span></span></code></pre></div></details>`,28)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
